import{z as i,x as s,o as l,c as p,q as t,j as n,D as e,d as B,s as r,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"供应链图谱","description":"","frontmatter":{"title":"供应链图谱","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-supply-graph.md","filePath":"quant/alt-supply-graph.md","lastUpdated":1791063341000}'),C={name:"quant/alt-supply-graph.md"};function d(F,E,h,m,D,u){const A=s("Mermaid");return l(),p("div",null,[E[2]||(E[2]=t('<h1 id="供应链图谱" tabindex="-1">供应链图谱 <a class="header-anchor" href="#供应链图谱" aria-label="Permalink to &quot;供应链图谱&quot;">​</a></h1><div class="epigraph"><p>行业分类把公司按相似分桶，供应链把它们按依赖连边；冲击沿边传播，不沿桶传播。</p><footer>—— 据 Cohen and Frazzini, Journal of Finance, 2008；Hoberg and Phillips, Journal of Political Economy, 2016 整理</footer></div><p><a href="/quant/alt-text-deep">上一课</a>把文本立成带验收的表征阶梯：残差增量不过门，就不升级。那台机器的产出不必只是一个分数——把文档之间的相似度变成公司之间的<strong>边</strong>，文本就从情绪工具变成图谱材料，这是本课。<a href="/quant/supply-chain-alt">供应链另类数据</a>已经立了经济联系与收益可预测性：Cohen–Frazzini 的贸易边、货运指数先分解再交易、边必须滞后到可获得。本课做工程：边从哪来、怎么存、怎么在滞后纪律下变成信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干课留下的缺口是边的<strong>供给与质量</strong>。披露边稀疏而滞后：占收入门槛以上的客户才要求披露，且一年只随年报更新一次。文本边多假阳性：产品相似不等于存在交易，竞争者之间相似度最高。物流边贵而慢：提单与船舶数据按条计价，覆盖不均。三个工程问题随之而来：一条边<strong>何时可得</strong>（关系披露在事后，用同期边回测就是前视）；一条边<strong>多稳定</strong>（客户关系会切换，边本身有半衰期）；<strong>节点对齐</strong>——大客户常是私营或海外公司，不在你的股票宇宙里，边的一端挂在无处交易的名字上。</p><p><span class="marginnote">图谱里的「节点」就是公司，「边」是公司之间的关系线：A 是 B 的大客户，A—B 之间就有一条边。供应链数据的价值在于冲击像水波一样沿边一圈圈传开；而行业分类只是把相似的公司装进同一个桶，桶与桶之间没有水流。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三源边，各带置信与时间戳。披露边：解析年报客户名单，边的可得时间取披露日，不是财政年度末；美国 S-K 条例要求披露占收入 \\(10\\%\\) 及以上的客户依赖，所以单家公司的披露边通常只有零到几条，稀疏是制度属性，不是解析缺陷。文本边：用上一课的 \\(L_3\\) 嵌入对产品描述取余弦相似度，每家公司只保留最近邻的若干条——Hoberg–Phillips（2016）的做法，行业边界随产品演进内生移动。物流边：提单与运量聚合到公司对，频率低但方向硬。边表统一 schema：起点、终点、类型、可得日期、置信度，刷新与失效走公司行动日历。信号端两条：邻居的滞后收益与邻居的盈余惊喜向本公司传播，Cohen–Frazzini 的原始发现正是滞后一个月的邻居收益仍可预测；客户集中度本身作为风险特征进入横截面。</p><p><span class="marginnote">「占收入 10% 以上才披露」意味着：一家年收入 200 亿的公司，只有单家客户贡献超过 20 亿才会上名单。所以披露出的客户往往只有一两条边，其余几千条贸易关系在文件里根本不存在——稀疏不是解析器的错，是披露制度的边界。</span></p>',9)),(l(),n(o,null,{default:e(()=>[r(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%B9%B4%E6%8A%A5%E5%AE%A2%E6%88%B7%E5%90%8D%E5%8D%95%EF%BC%9A%E6%8A%AB%E9%9C%B2%E8%BE%B9%22%5D%20--%3E%20EDGE%5B%22%E8%BE%B9%E8%A1%A8%EF%BC%9A%E5%8F%AF%E5%BE%97%E6%97%A5%E6%9C%9F%E5%8A%A0%E7%BD%AE%E4%BF%A1%E5%BA%A6%22%5D%0A%20%20T%5B%22%E4%BA%A7%E5%93%81%E6%8F%8F%E8%BF%B0%E5%B5%8C%E5%85%A5%EF%BC%9A%E6%96%87%E6%9C%AC%E8%BE%B9%22%5D%20--%3E%20EDGE%0A%20%20L%5B%22%E6%8F%90%E5%8D%95%E4%B8%8E%E8%BF%90%E9%87%8F%EF%BC%9A%E7%89%A9%E6%B5%81%E8%BE%B9%22%5D%20--%3E%20EDGE%0A%20%20EDGE%20--%3E%20LAG%5B%22%E6%BB%9E%E5%90%8E%E5%88%B0%E5%8F%AF%E5%BE%97%E6%97%A5%22%5D%20--%3E%20P%5B%22%E9%82%BB%E5%B1%85%E6%94%B6%E7%9B%8A%E4%B8%8E%E7%9B%88%E4%BD%99%E6%83%8A%E5%96%9C%E4%BC%A0%E6%92%AD%22%5D%0A%20%20P%20--%3E%20S1%5B%22%E4%BC%A0%E5%AF%BC%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20EDGE%20--%3E%20C%5B%22%E5%AE%A2%E6%88%B7%E9%9B%86%E4%B8%AD%E5%BA%A6%E7%89%B9%E5%BE%81%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("边比桶好的机制在传导结构：冲击沿投入产出网络放大与衰减（Acemoglu et al., 2012；Carvalho et al., 2021），行业桶只在分类修订时才动，而文本边随产品线季度级演进——这正是 Hoberg–Phillips 强调的内生差异化。不这么做的错法有两条对称的：用"),a("strong",null,"同期"),B("关系回测，把事后才披露的客户当成了当时已知，等于在回测里开了天眼；用行业桶近似供应链，把竞争者与交易对手混为一谈——竞争者收益同向是因为共同因子，贸易伙伴收益领先是因为传导，二者的交易含义相反。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"边的一端不在股票宇宙，边没有失效：传导到可交易的最近上市公司，正是这条边的用法之一——供应商多为私营时，其上市客户的共同供应商暴露仍可计算。直接把不可交易节点剔出图谱，等于把传导链掐断在最有信息的一段。")],-1)),E[6]||(E[6]=a("p",null,"一个盈余惊喜沿两种边走出的不同路径——回答「为什么贸易伙伴与竞争者的交易含义相反」：",-1)),(l(),n(o,null,{default:e(()=>[r(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22A%20%E5%85%AC%E5%8F%B8%E5%8F%91%E5%B8%83%E7%9B%88%E4%BD%99%E6%83%8A%E5%96%9C%22%5D%20--%3E%7C%22%E8%B4%B8%E6%98%93%E4%BC%99%E4%BC%B4%E8%BE%B9%EF%BC%88%E5%AE%A2%E6%88%B7%2F%E4%BE%9B%E5%BA%94%E5%95%86%EF%BC%89%22%7C%20T1%5B%22%E4%B8%8A%E4%B8%8B%E6%B8%B8%E5%85%AC%E5%8F%B8%E5%9C%A8%E4%B9%8B%E5%90%8E%E6%95%B0%E6%9C%88%E9%80%90%E6%B8%90%E8%B7%9F%E9%9A%8F%22%5D%0A%20%20T1%20--%3E%20TR%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%EF%BC%9A%E5%9C%A8%E8%B7%9F%E9%9A%8F%E8%80%85%E5%8A%A8%E8%B5%B7%E6%9D%A5%E4%B9%8B%E5%89%8D%E5%BB%BA%E4%BB%93%22%5D%0A%20%20SHOCK%20--%3E%7C%22%E7%AB%9E%E4%BA%89%E8%80%85%E8%BE%B9%EF%BC%88%E5%90%8C%E8%A1%8C%E4%B8%9A%E6%A1%B6%EF%BC%89%22%7C%20T2%5B%22%E5%90%8C%E8%A1%8C%E4%B8%9A%E5%85%AC%E5%8F%B8%E5%BD%93%E6%97%A5%E5%90%8C%E6%AD%A5%E6%B6%A8%E8%B7%8C%22%5D%0A%20%20T2%20--%3E%20CR%5B%22%E5%85%B1%E5%90%8C%E5%9B%A0%E5%AD%90%E9%A9%B1%E5%8A%A8%EF%BC%8C%E4%B8%8D%E6%98%AF%E4%BC%A0%E5%AF%BC%22%5D%0A%20%20TR%20--%3E%20X%5B%22%E4%B8%A4%E7%A7%8D%E8%BE%B9%E5%90%AB%E4%B9%89%E7%9B%B8%E5%8F%8D%EF%BC%8C%E6%B7%B7%E7%94%A8%E5%8D%B3%E5%8F%8D%E5%90%91%22%5D%0A%20%20CR%20--%3E%20X%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理地理聚集——把边投影到地图上是下一课的对象；货运指数的需求、供给与拥塞分解主干课已给，不重讲。文本边在产品同质的行业（大宗商品、基础金融）里退化，近邻与自身几乎同分布；私营对手方的集中度披露缺失会使边系统性偏向大公司样本。传导信号换手高于基本面因子，费用与容量按执行课的口径评估，不在本课展开。</p><p><span class="marginnote">为什么大宗商品行业文本边会退化：两家炼铜厂的产品描述几乎逐字相同，余弦相似度接近 1，但它们彼此是竞争者而非客户。近邻分不清「像」与「买」——这类行业里文本边必须降权或停用，否则会把竞争共振误读成供应链传导。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图谱的材料是三类边：披露、文本、物流，统一存可得日期与置信度，稀疏是制度属性。</li><li>一切传导信号先滞后到可得日；同期边回测即前视。</li><li>文本边来自上一课的表征阶梯，行业边界随产品内生移动，比分类桶更贴近传导。</li><li>集中度本身是风险特征；不可交易端点保留，向可交易端传导。</li><li>出处：Cohen and Frazzini, <em>JF</em>, 2008；Menzly and Ozbas, 2010；Hoberg and Phillips, <em>JPE</em>, 2016；Acemoglu, Carvalho, Ozdaglar and Tahbaz-Salehi, <em>Econometrica</em>, 2012；Carvalho, Nirei, Saito and Tahbaz-Salehi, <em>QJE</em>, 2021。</li></ul>',5))])}const c=i(C,[["render",d]]);export{f as __pageData,c as default};
